<script>
    /* currency: one state for every option; placeholder rates as on the homepage */
(function () {
  const R = { usd: 1, eur: .86, gbp: .75 }, S = { usd: '$', eur: '€', gbp: '£' };
  const C = {
    code: 'usd', fmt(v) { return S[C.code] + (v * R[C.code]).toFixed(2); },
    set(c) {
      C.code = c; document.querySelectorAll('[data-p]').forEach(el => el.textContent = C.fmt(+el.dataset.p));
      document.querySelectorAll('.cur').forEach(w => { w.querySelector('button span').textContent = c.toUpperCase(); w.querySelectorAll('li').forEach(li => li.classList.toggle('on', li.dataset.c === c)); });
    }
  };
  document.addEventListener('click', e => {
    const li = e.target.closest('.cur li'); if (li) { C.set(li.dataset.c); li.closest('.cur').classList.remove('open'); return; }
    const b = e.target.closest('.cur button'); document.querySelectorAll('.cur.open').forEach(w => { if (!b || w !== b.parentNode) { w.classList.remove('open'); w.querySelector('button').setAttribute('aria-expanded', 'false'); } });
    if (b) { const w = b.parentNode, o = w.classList.toggle('open'); b.setAttribute('aria-expanded', o); }
  });
  RS.cur = C;
})();

/* night skies: three builds of the same hero, one WebGL sky each, constellations on top */
(function () {
  const A = window.__DW_ASSETS;
  const IW = 2400, IH = 1355, MOON = [.205, .695];

  // constellation shapes in a unit box, placed by screen fraction
  const K = [
    { n: 'e-books', c: 'Read at your own pace', bx: [.06, .15, .16, .23], p: [[0, .25], [.48, .08], [.5, .9], [0, 1], [1, .25], [.52, .08], [1, 1]], e: [[0, 1], [1, 2], [2, 3], [3, 0], [4, 5], [5, 2], [2, 6], [6, 4]] },
    { n: 'videos', c: 'Watch it done, then do it', bx: [.79, .17, .13, .22], p: [[0, 0], [1, .5], [0, 1], [.3, .5]], e: [[0, 1], [1, 2], [2, 0], [0, 3], [3, 2]] },
    { n: 'software', c: 'Plugins and tools for your site', bx: [.08, .5, .12, .11], p: [[.3, 0], [0, .5], [.3, 1], [.7, 0], [1, .5], [.7, 1], [.58, .05], [.42, .95]], e: [[0, 1], [1, 2], [3, 4], [4, 5], [6, 7]] },
    { n: 'templates', c: 'Start from a finished layout', bx: [.78, .52, .14, .17], p: [[0, 0], [1, 0], [1, 1], [0, 1], [0, .32], [1, .32], [.45, .32], [.45, 1]], e: [[0, 1], [1, 2], [2, 3], [3, 0], [4, 5], [6, 7]] }
  ];
  const MOB = [[.06, .5, .3, .09], [.62, .48, .24, .1], [.08, .63, .24, .07], [.6, .62, .3, .08]];
  const boxOf = (ci, w) => w < 820 ? MOB[ci] : K[ci].bx;

  /* small GL kit */
  function gl2(cv) { try { return cv.getContext('webgl2', { antialias: false, alpha: false, premultipliedAlpha: false, powerPreference: 'high-performance' }); } catch (e) { return null; } }
  function prog(gl, vs, fs) {
    const sh = (t, s) => { const x = gl.createShader(t); gl.shaderSource(x, s); gl.compileShader(x); if (!gl.getShaderParameter(x, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(x)); return x; };
    const p = gl.createProgram(); gl.attachShader(p, sh(gl.VERTEX_SHADER, vs)); gl.attachShader(p, sh(gl.FRAGMENT_SHADER, fs)); gl.linkProgram(p); if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p));
    const u = {}; const n = gl.getProgramParameter(p, gl.ACTIVE_UNIFORMS); for (let i = 0; i < n; i++) { const a = gl.getActiveUniform(p, i); u[a.name.replace('[0]', '')] = gl.getUniformLocation(p, a.name); } return { p, u };
  }
  const QUAD_VS = `#version 300 es
in vec2 a;void main(){gl_Position=vec4(a,0.,1.);}`;
  function quad(gl) { const b = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, b); gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW); return b; }
  const NOISE = `
float h21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
vec2 h22(vec2 p){float n=h21(p);return vec2(n,h21(p+n+.17));}
float vn(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h21(i),h21(i+vec2(1,0)),f.x),mix(h21(i+vec2(0,1)),h21(i+vec2(1,1)),f.x),f.y);}
float fbm(vec2 p){float s=0.,a=.5;for(int i=0;i<5;i++){s+=a*vn(p);p=p*2.03+vec2(1.7,9.2);a*=.5;}return s;}
float fbm3(vec2 p){float s=0.,a=.5;for(int i=0;i<3;i++){s+=a*vn(p);p=p*2.07+vec2(5.1,1.3);a*=.5;}return s/.875;}`;

  // shared sky body: gradient, milky way, stars, moon. Coordinates p are in screen heights.
  const SKY = `
uniform vec2 uRes;uniform float uTime;uniform vec2 uMouse;uniform vec2 uMoon;uniform float uHor;
vec3 skyBase(vec2 uv){
  float y=uv.y;
  vec3 zen=vec3(.012,.03,.07),mid=vec3(.02,.07,.13),hor=vec3(.03,.2,.24);
  vec3 c=mix(hor,mid,smoothstep(uHor,uHor+.32,y));c=mix(c,zen,smoothstep(uHor+.25,1.,y));
  c+=vec3(.02,.17,.18)*exp(-max(y-uHor,0.)*7.)*(.35+.65*smoothstep(.25,.95,uv.x));
  return c;}
float band(vec2 p,out float along){vec2 c=vec2(.95,.42);vec2 d=normalize(vec2(.62,.78));vec2 q=p-c;along=dot(q,d);float v=dot(q,vec2(-d.y,d.x));
  float w=.16+.06*sin(along*3.1);return exp(-v*v/(w*w));}
vec3 milky(vec2 p,float b,float along){
  float n=fbm(p*vec2(3.,3.)+vec2(along*2.,0.));float dust=fbm(p*7.+3.1);
  float glow=b*smoothstep(.2,.85,n)*1.05;glow*=1.-.75*smoothstep(.45,.7,dust)*b;
  return glow*mix(vec3(.22,.5,.6),vec3(.8,.86,.95),n*n);}
vec3 starLayer(vec2 p,float b,int l,float live){
  float sc=(l==0?22.:(l==1?48.:105.));vec2 q=p*sc;vec2 id=floor(q);vec2 f=fract(q)-.5;
  float h=h21(id+float(l)*17.3);float thr=(l==0?.955:(l==1?.9:.82))-b*(l==2?.32:.1);
  if(h<=thr)return vec3(0);
  vec2 o2=(h22(id)-.5)*.7;float d=length(f-o2)/(l==0?1.:(l==1?1.4:2.));
  float m=(h-thr)/(1.-thr);
  // calm twinkle: only one star in five breathes, slowly
  float tw=1.;if(live>.5&&fract(h*91.7)<.2)tw=.82+.18*sin(uTime*(.35+fract(h*13.)*.6)+h*80.);
